style.css:
@-moz-document domain("youtube.com") {
/* General text styling with monospace font */
    body, div, span, h1, h2, h3, p, button, input, textarea, a {
        font-family: "Courier New", Courier, monospace; /* Monospace font */
        color: #b39682 !important; /* Soft brown color */
    }

    /* Background color */
    ytd-app, ytd-page-manager, ytd-browse {
        background-color: #ffffff !important; /* White background */
    }

    /* Video title and descriptions */
    ytd-video-primary-info-renderer h1, ytd-video-secondary-info-renderer p {
        color: #b39682 !important; /* Soft brown text */
    }

    /* Sidebar and navigation */
    ytd-app #guide {
        background-color: #f5e4d1 !important; /* Light brown sidebar */
    }

    /* Buttons (like 'Like', 'Dislike', 'Share', 'Subscribe') */
    ytd-video-primary-info-renderer yt-button-shape, 
    ytd-menu-renderer yt-button-shape, 
    ytd-comment-action-buttons-renderer yt-button-shape {
        background-color: #b39682 !important; /* Soft brown buttons */
        color: #ffffff !important; /* White text on buttons */
        border-radius: 8px !important; /* Rounded corners */
    }

    /* Button hover effect */
    ytd-video-primary-info-renderer yt-button-shape:hover,
    ytd-menu-renderer yt-button-shape:hover,
    ytd-comment-action-buttons-renderer yt-button-shape:hover {
        background-color: #9c8067 !important; /* Darker brown on hover */
        border-radius: 8px !important;
    }

    /* Video cards and thumbnails */
    ytd-rich-grid-renderer ytd-rich-item-renderer {
        border: 3px solid #b39682 !important; /* Soft brown border around video cards */
        border-radius: 8px !important; /* Rounded corners */
    }

    /* Video hover effect */
    ytd-rich-grid-renderer ytd-rich-item-renderer:hover {
        border-color: #9c8067 !important; /* Darker brown border on hover */
    }

    /* Comment section */
    ytd-comments #content-text, ytd-comments #author-text {
        color: #b39682 !important; /* Brown text for comments */
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 8px !important;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #b39682 !important; /* Soft brown scrollbar */
        border-radius: 10px !important; /* Rounded scrollbar thumb */
    }
    ::-webkit-scrollbar-thumb:hover {
        background-color: #9c8067 !important; /* Darker brown on hover */
    }

    /* Active/clicked state: Rounded brown highlight */
    button:active, a:active {
        outline: 2px solid #b39682 !important; /* Brown outline for active state */
        outline-offset: -4px !important;
        border-radius: 12px !important; /* Rounded corners when clicked */
    }

    /* Video player controls */
    ytd-player #movie_player .ytp-chrome-top, 
    ytd-player #movie_player .ytp-chrome-bottom {
        background-color: #b39682 !important; /* Brown control bar */
    }

    /* Hover effect for video player controls */
    ytd-player #movie_player .ytp-chrome-top:hover,
    ytd-player #movie_player .ytp-chrome-bottom:hover {
        background-color: #9c8067 !important; /* Darker brown on hover */
    }

    /* Text for headlines and descriptions */
    .style-scope.ytd-rich-grid-renderer, .style-scope.ytd-video-primary-info-renderer {
        color: #b39682 !important; /* Brown text */
    }

    /* Search bar */
    ytd-searchbox input {
        background-color: #ffffff !important; /* White background for search bar */
        border: 1px solid #b39682 !important; /* Soft brown border */
        color: #b39682 !important; /* Brown text */
        border-radius: 8px !important; /* Rounded corners */
    }

    ytd-searchbox input:hover {
        border-color: #9c8067 !important; /* Darker brown border on hover */
        border-radius: 12px !important; /* Rounded corners on hover */
    }
}
